&lt;div style="margin: 0px; padding: 0px; color: rgb(51, 51, 51); font-family: Verdana, arial, Geneva, Helvetica, Century; font-size: 16px; background-color: rgb(255, 255, 255);"&gt;
&lt;p&gt;&lt;strong&gt;Media contact:&nbsp;&lt;/strong&gt;Erica Heartquist,&nbsp;&lt;a href="mailto:PHD.Communications@oha.oregon.gov" rel="noopener" style="color: rgb(6, 66, 118); text-decoration-line: none; text-size-adjust: 100%;" target="_blank"&gt;PHD.Communications@oha.oregon.gov&lt;/a&gt;&amp;nbsp;&lt;/p&gt;
