     &lt;/li&gt;
     &lt;li dir="ltr"&gt;
     &lt;p dir="ltr"&gt;&lt;span style="font-size:12px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Santa and Mrs. Claus greeting families. &lt;strong&gt;Grand arrival at 3:00 pm&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
     &lt;li dir="ltr"&gt;
     &lt;p dir="ltr"&gt;&lt;span style="font-size:12px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Holiday decorations, cookies, and cocoa.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
     &lt;li dir="ltr"&gt;
     &lt;p dir="ltr"&gt;&lt;span style="font-size:12px"&gt;&lt;span style="font-family:arial,helvetica,sans-serif"&gt;Local artwork and gingerbread display.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
     &lt;/li&gt;
